#include <hb.h>
#include <hb-ot.h>
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <font_file>\n", argv[0]);
        return 1;
    }

    const char *path = argv[1];
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *data = (char *)malloc(len);
    fread(data, 1, len, f);
    fclose(f);

    hb_blob_t *blob = hb_blob_create(data, len, HB_MEMORY_MODE_WRITABLE, data, free);
    hb_face_t *face = hb_face_create(blob, 0);
    hb_font_t *font = hb_font_create(face);

    hb_buffer_t *buf = hb_buffer_create();
    hb_buffer_add_utf8(buf, "A", 1, 0, 1);
    hb_buffer_guess_segment_properties(buf);

    hb_shape(font, buf, NULL, 0);

    unsigned int count = hb_buffer_get_length(buf);
    hb_glyph_info_t *info = hb_buffer_get_glyph_infos(buf, NULL);
    for (unsigned int i = 0; i < count; i++) {
        printf("glyph %u: %u\n", i, info[i].codepoint);
    }

    hb_buffer_destroy(buf);
    hb_font_destroy(font);
    hb_face_destroy(face);
    hb_blob_destroy(blob);

    return 0;
}
